content.content:
1	role: Aggregator
2	replicas: ${replicas}
3	podAnnotations:
4	  reloader.stakater.com/auto: "true"
5	service:
6	  enabled: true
7	  type: ClusterIP
8	  ports:
9	    - name: otlp-grpc
10	      port: 4317
11	      protocol: TCP
12	    - name: otlp-http
13	      port: 4318
14	      protocol: TCP
15	    - name: dd-agent
16	      port: 8282
17	      protocol: TCP
18	env:
19	  - name: DATADOG_API_KEY
20	    valueFrom:
21	      secretKeyRef:
22	        name: vector-datadog
23	        key: api_key
24	resources:
25	  requests:
26	    cpu: ${requests_cpu}
27	    memory: ${requests_memory}
28	  limits:
29	    cpu: "${limits_cpu}"
30	    memory: ${limits_memory}
31	podDisruptionBudget:
32	  enabled: true
33	  minAvailable: 2
34	
35	topologySpreadConstraints:
36	  - maxSkew: 1
37	    topologyKey: topology.kubernetes.io/zone
38	    whenUnsatisfiable: ScheduleAnyway
39	    labelSelector:
40	      matchLabels:
41	        app.kubernetes.io/name: vector
42	
43	affinity:
44	  podAntiAffinity:
45	    preferredDuringSchedulingIgnoredDuringExecution:
46	      - weight: 100
47	        podAffinityTerm:
48	          topologyKey: kubernetes.io/hostname
49	          labelSelector:
50	            matchLabels:
51	              app.kubernetes.io/name: vector
52	
53	%{ if service_monitor_enabled ~}
54	serviceMonitor:
55	  enabled: true
56	%{ endif ~}
57	customConfig:
58	  data_dir: /vector-data-dir
59	  api:
60	    enabled: true
61	    address: 127.0.0.1:8686
62	  sources:
63	    otlp_in:
64	      type: opentelemetry
65	      grpc:
66	        address: 0.0.0.0:4317
67	      http:
68	        address: 0.0.0.0:4318
69	    dd_agent_in:
70	      type: datadog_agent
71	      address: 0.0.0.0:8282
72	      multiple_outputs: true
73	      disable_metrics: true
74	      disable_traces: true
75	      store_api_key: false
76	      acknowledgements:
77	        enabled: true
78	  transforms:
79	    drop_audit:
80	      type: filter
81	      inputs:
82	        - otlp_in.logs
83	        - dd_agent_in.logs
84	      condition: |
85	        msg = if is_string(.message) { string!(.message) } else { "" }
86	        ${audit_drop_condition}
87	%{ if email_redaction_enabled ~}
88	    redact_emails_logs:
89	      type: remap
90	      inputs:
91	        - drop_audit
92	      source: |
93	        email_re = r'[\w._%+\-]+@[\w.-]+\.[A-Za-z]{2,}'
94	        if is_string(.message) {
95	          .message = replace(string!(.message), email_re, "${email_redaction_replacement}")
96	        }
97	        if is_object(.attributes) {
98	          attrs, _err = object(.attributes)
99	          if is_object(attrs) {
100	            .attributes = map_values(attrs) -> |v| {
101	              if is_string(v) { replace(string!(v), email_re, "${email_redaction_replacement}") } else { v }
102	            }
103	          }
104	        }
105	    redact_emails_traces:
106	      type: remap
107	      inputs:
108	        - otlp_in.traces
109	      source: |
110	        email_re = r'[\w._%+\-]+@[\w.-]+\.[A-Za-z]{2,}'
111	        if is_object(.attributes) {
112	          attrs, _err = object(.attributes)
113	          if is_object(attrs) {
114	            .attributes = map_values(attrs) -> |v| {
115	              if is_string(v) { replace(string!(v), email_re, "${email_redaction_replacement}") } else { v }
116	            }
117	          }
118	        }
119	        if is_object(.resource) {
120	          res, _err = object(.resource)
121	          if is_object(res) && is_object(res.attributes) {
122	            rattrs, _err2 = object(res.attributes)
123	            if is_object(rattrs) {
124	              .resource.attributes = map_values(rattrs) -> |v| {
125	                if is_string(v) { replace(string!(v), email_re, "${email_redaction_replacement}") } else { v }
126	              }
127	            }
128	          }
129	        }
130	    redact_emails_metrics:
131	      type: remap
132	      inputs:
133	        - otlp_in.metrics
134	      source: |
135	        email_re = r'[\w._%+\-]+@[\w.-]+\.[A-Za-z]{2,}'
136	        if is_object(.attributes) {
137	          attrs, _err = object(.attributes)
138	          if is_object(attrs) {
139	            .attributes = map_values(attrs) -> |v| {
140	              if is_string(v) { replace(string!(v), email_re, "${email_redaction_replacement}") } else { v }
141	            }
142	          }
143	        }
144	        if is_object(.resource) {
145	          res, _err = object(.resource)
146	          if is_object(res) && is_object(res.attributes) {
147	            rattrs, _err2 = object(res.attributes)
148	            if is_object(rattrs) {
149	              .resource.attributes = map_values(rattrs) -> |v| {
150	                if is_string(v) { replace(string!(v), email_re, "${email_redaction_replacement}") } else { v }
151	              }
152	            }
153	          }
154	        }
155	%{ endif ~}
156	  sinks:
157	    datadog_logs:
158	      type: datadog_logs
159	      inputs:
160	        - ${email_redaction_enabled ? "redact_emails_logs" : "drop_audit"}
161	      default_api_key: $${DATADOG_API_KEY}
162	      site: ${datadog_site}
163	    datadog_traces:
164	      type: datadog_traces
165	      inputs:
166	        - ${email_redaction_enabled ? "redact_emails_traces" : "otlp_in.traces"}
167	      default_api_key: $${DATADOG_API_KEY}
168	      site: ${datadog_site}
169	    datadog_metrics:
170	      type: datadog_metrics
171	      inputs:
172	        - ${email_redaction_enabled ? "redact_emails_metrics" : "otlp_in.metrics"}
173	      default_api_key: $${DATADOG_API_KEY}
174	      site: ${datadog_site}
